contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount, uint lockTime) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);
        require(amount >= 0);

        uint balBefore = address(this).balance;
        uint contractBefore = address(c).balance;

        c.Put{value: amount}(lockTime); if (__ESBMC_reverted()) return;

        (uint unlockTime, uint recordedBalance) = c.Acc(address(this)); if (__ESBMC_reverted()) return;

        uint balAfter = address(this).balance;
        uint contractAfter = address(c).balance;

        assert(balBefore - balAfter == recordedBalance + (contractAfter - contractBefore));
    }

    receive() external payable {}
}

