// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _run(uint256 amount, uint256 lockTime) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        vm.assume(amount >= 0);
        uint balBefore = address(this).balance;
        uint contractBefore = address(c).balance;
        try c.Put{value: amount}(lockTime) {} catch { return; }
        uint256 unlockTime;
        uint256 recordedBalance;
        try c.Acc(address(this)) returns (uint256 __r0, uint256 __r1) { unlockTime = __r0; recordedBalance = __r1; } catch { return; }
        uint balAfter = address(this).balance;
        uint contractAfter = address(c).balance;
        assertTrue(balBefore - balAfter == recordedBalance + (contractAfter - contractBefore));
    }

    function testFuzz_run(uint256 amount, uint256 lockTime) public {
        _run(amount, lockTime);
    }

    receive() external payable {}
}
